contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call
    // params: from, target contract address, list of tos, value v
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);

        // We will call c.transfer and observe whether it reverted and the returned bool.
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // dummy when reverted
        }

        // General rule: transfer never successfully returns false. If it returns, it must be true.
        // Also if it returns (i.e. not reverted) then it must have returned true.
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

